CREATE TABLE Juizes (
id INT PRIMARY KEY,
nome VARCHAR(100)
);
CREATE TABLE Audiencias (
id INT PRIMARY KEY,
juiz_id INT,
status VARCHAR(20),
FOREIGN KEY (juiz_id) REFERENCES Juizes(id)
);
