CREATE VIEW Relatorio_Audiencias AS
SELECT j.nome AS juiz, COUNT(*) AS total_concluidas
FROM Audiencias a
JOIN Juizes j ON a.juiz_id = j.id
WHERE a.status = 'Concluída'
GROUP BY j.nome
HAVING COUNT(*) > 1;
