Uma Secretaria da Fazenda está estruturando seu banco de dados para garantir a integridade e a eficiência das consultas sobre as fiscalizações historicamente realizadas. Para isso, foi criada uma estrutura relacional robusta, da qual fazem parte as tabelas abaixo. Considera-se que uma empresa pode ser fiscalizada várias vezes.
CREATE TABLE EMPRESA (
id_empresa INT PRIMARY KEY,
nome VARCHAR(255) NOT NULL
);
CREATE TABLE FISCALIZACAO (
 id_fiscalizacao INT PRIMARY KEY,
 id_empresa INT,
 data_fiscalizacao DATE NOT NULL,
 status VARCHAR(20) NOT NULL,
 FOREIGN KEY (id_empresa) REFERENCES EMPRESA (id_empresa) ON DELETE CASCADE
);
Em condições ideais, um comportamento correto resultante dessa estrutura é:

alts:
SELECT id_empresa, COUNT(DISTINCT id_fiscalizacao) AS total_fiscalizacoes,
COUNT(valor_multa) AS total_arrecadado
FROM FISCALIZACAO WHERE status = 'Concluida' GROUP BY id_empresa;

SELECT s.nome
FROM servidores s, historico_carga h
WHERE s.id_servidor = h.id_servidor AND h.carga_atual / s.capacidade > 0.8;

SELECT s.nome FROM servidores s
WHERE EXISTS (SELECT 1 FROM historico_carga h
WHERE h.id_servidor = s.id_servidor AND h.carga_atual > 0.8);

SELECT DISTINCT s.nome FROM servidores s
JOIN historico_carga h ON s.id_servidor = h.id_servidor
WHERE h.carga_atual > 0.8 * s.capacidade;

